mapper.select:
SELECT id, source, topic_name AS topicName, period,
       snapshot_date AS snapshotDate, data_json AS dataJson, create_time AS createTime
FROM leaderboard_snapshot
WHERE source = #{source}
  AND (topic_name = #{topicName} OR (#{topicName} IS NULL AND topic_name IS NULL))
  AND period = #{period}
  AND snapshot_date = #{snapshotDate}
LIMIT 1
